// app/products/page.js
import ProductList from './ProductList';

export default function ProductsPage() {
  return (
    <div>
      <h1>Products</h1>
      <ProductList />
    </div>
  );
}

// app/products/ProductList.js
import { Suspense } from 'react';
import ErrorTrigger from './ErrorTrigger';

async function getProducts() {
  const res = await fetch('https://fakestoreapi.com/products');
  return res.json();
}

export default async function ProductList() {
  const products = await getProducts();
  return (
    <>
      <ul>
        {products.map(p => <li key={p.id}>{p.title}</li>)}
      </ul>
      <ErrorTrigger />
    </>
  );
}

// app/products/ErrorTrigger.js
'use client';
import { useState } from 'react';

export default function ErrorTrigger() {
  const [crash, setCrash] = useState(false);
  if (crash) {
    throw new Error('Simulated crash in ProductList');
  }
  return <button onClick={() => setCrash(true)}>Trigger Error</button>;
}

// app/products/error.js
'use client';

export default function ProductsError({ error, reset }) {
  return (
    <div>
      <h2>Product section crashed!</h2>
      <p>{error.message}</p>
      <button onClick={() => reset()}>Try again</button>
    </div>
  );
}
